/**
 * Deterministic renderers for the central integration files generated by the
 * Factory. Each renderer produces the full content of one composition file from
 * the known integration requests declared by capability overlays. Outputs only
 * depend on the (already validated) integration entries, in declaration order.
 */

const BANNER = '// GENERATED BY ENISTERE FACTORY — capability composition. Do not edit manually.';

function assertKnown(integrations, allowed) {
  for (const integration of integrations) {
    if (!allowed.includes(integration.kind)) throw new Error(`Unknown integration kind: ${integration.kind}`);
  }
}

/**
 * Orders the global guard chain deterministically by the declared `order`,
 * independently of capability composition order. Rejects a symbol declared twice
 * and two guards claiming the same slot (an ambiguous chain is never rendered).
 */
export function orderGlobalGuards(guards) {
  const bySymbol = new Map();
  const byOrder = new Map();
  for (const guard of guards) {
    if (bySymbol.has(guard.symbol)) throw new Error(`Duplicate global guard: ${guard.symbol}`);
    if (byOrder.has(guard.order)) {
      throw new Error(`Ambiguous global guard order ${guard.order}: ${byOrder.get(guard.order)} and ${guard.symbol}`);
    }
    bySymbol.set(guard.symbol, guard);
    byOrder.set(guard.order, guard.symbol);
  }
  return [...guards].sort((a, b) => a.order - b.order);
}

/** src/composition/capabilities.ts of the NestJS app. */
export function renderNestjsComposition(integrations) {
  assertKnown(integrations, ['nestjs.module', 'nestjs.global-guard', 'nestjs.throttler']);
  const orderedGuards = orderGlobalGuards(integrations.filter((item) => item.kind === 'nestjs.global-guard'));
  const imported = [
    ...integrations.filter((item) => item.kind === 'nestjs.module'),
    ...orderedGuards,
  ];
  const importLines = [...new Set(imported.map((item) => `import { ${item.symbol} } from '${item.importPath}';`))];
  const modules = integrations.filter((item) => item.kind === 'nestjs.module').map((item) => `  ${item.symbol},`);
  const guards = orderedGuards.map((item) => `  ${item.symbol}, // order ${item.order}`);
  const throttlers = integrations.filter((item) => item.kind === 'nestjs.throttler').map((item) => [
    '  {',
    `    name: '${item.name}',`,
    `    limitEnv: '${item.limitEnv}',`,
    `    defaultLimit: ${item.defaultLimit},`,
    `    ttlSecondsEnv: '${item.ttlSecondsEnv}',`,
    `    defaultTtlSeconds: ${item.defaultTtlSeconds},`,
    '  },',
  ].join('\n'));
  return [
    BANNER,
    "import type { CanActivate, DynamicModule, ForwardReference, Type } from '@nestjs/common';",
    ...importLines,
    '',
    'export interface CapabilityThrottlerSpec {',
    '  name: string;',
    '  limitEnv: string;',
    '  defaultLimit: number;',
    '  ttlSecondsEnv: string;',
    '  defaultTtlSeconds: number;',
    '}',
    '',
    '/** Modules contributed by the composed capabilities (AppModule imports). */',
    'export const CAPABILITY_MODULES: Array<Type | DynamicModule | ForwardReference> = [',
    ...modules,
    '];',
    '',
    '/** Global guards contributed by the composed capabilities, in order. */',
    'export const CAPABILITY_GLOBAL_GUARDS: Array<Type<CanActivate>> = [',
    ...guards,
    '];',
    '',
    '/** Named throttlers contributed by the composed capabilities. */',
    'export const CAPABILITY_THROTTLERS: CapabilityThrottlerSpec[] = [',
    ...throttlers,
    '];',
    '',
  ].join('\n');
}

/** src/app/providers/capability-providers.tsx of the Next.js app. */
export function renderNextjsCapabilityProviders(providers) {
  assertKnown(providers, ['nextjs.provider']);
  return renderProviderComposition(providers, '"use client";\n\n');
}

/** src/composition/capability-providers.tsx of the Expo app. */
export function renderExpoCapabilityProviders(providers) {
  assertKnown(providers, ['expo.provider']);
  return renderProviderComposition(providers, '');
}

function renderProviderComposition(providers, prefix) {
  const importLines = [...new Set(providers.map((item) => `import { ${item.symbol} } from '${item.importPath}';`))];
  const open = providers.map((item, index) => `${'  '.repeat(index + 1)}<${item.symbol}>`);
  const close = [...providers].reverse().map((item, index) => `${'  '.repeat(providers.length - index)}</${item.symbol}>`);
  const body = providers.length === 0
    ? ['  return <>{children}</>;']
    : ['  return (', ...open, `${'  '.repeat(providers.length + 1)}{children}`, ...close, '  );'];
  return [
    `${prefix}${BANNER}`,
    "import type { ReactElement, ReactNode } from 'react';",
    ...importLines,
    '',
    '/** Providers contributed by the composed capabilities, nested in order. */',
    'export function CapabilityProviders({ children }: { readonly children: ReactNode }): ReactElement {',
    ...body,
    '}',
    '',
  ].join('\n');
}

/** src/core/composition/public-nav.ts of the Next.js app. */
export function renderNextjsPublicNav(links) {
  assertKnown(links, ['nextjs.public-nav-link']);
  return [
    BANNER,
    'export interface CapabilityNavLink {',
    '  readonly href: string;',
    '  readonly label: string;',
    '}',
    '',
    '/** Public header links contributed by the composed capabilities. */',
    'export const CAPABILITY_PUBLIC_NAV_LINKS: readonly CapabilityNavLink[] = [',
    ...links.map((item) => `  { href: '${item.href}', label: '${item.label}' },`),
    '];',
    '',
  ].join('\n');
}

/**
 * src/core/composition/status-sections.tsx — registry of status-page sections
 * contributed by capabilities. Replaces overwriting the shared status page:
 * each capability declares a section with an explicit `order`; the shell renders
 * the registry. Duplicate symbols or ambiguous ranks are rejected.
 */
export function renderNextjsStatusSections(sections) {
  assertKnown(sections, ['nextjs.status-section']);
  const bySymbol = new Map();
  const byOrder = new Map();
  for (const section of sections) {
    if (bySymbol.has(section.symbol)) throw new Error(`Duplicate status section: ${section.symbol}`);
    if (byOrder.has(section.order)) {
      throw new Error(`Ambiguous status section order ${section.order}: ${byOrder.get(section.order)} and ${section.symbol}`);
    }
    bySymbol.set(section.symbol, section);
    byOrder.set(section.order, section.symbol);
  }
  const ordered = [...sections].sort((a, b) => a.order - b.order);
  const importLines = ordered.map((item) => `import { ${item.symbol} } from "${item.importPath}";`);
  return [
    `"use client";\n\n${BANNER}`,
    'import type { ComponentType } from "react";',
    ...importLines,
    '',
    'export interface CapabilityStatusSection {',
    '  readonly capability: string;',
    '  readonly order: number;',
    '  readonly Component: ComponentType;',
    '}',
    '',
    '/** Sections contribuées par les capabilities composées, dans l\'ordre déclaré. */',
    'export const CAPABILITY_STATUS_SECTIONS: readonly CapabilityStatusSection[] = [',
    ...ordered.map((item) => [
      '  {',
      `    capability: "${item.capability}",`,
      `    order: ${item.order},`,
      `    Component: ${item.symbol},`,
      '  },',
    ].join('\n')),
    '];',
    '',
  ].join('\n');
}

/** Appends a generated, commented environment section to a .env.example. */
export function renderEnvironmentSection(current, manifest) {
  const lines = [
    `# --- ${manifest.capability} capability (generated by Enistere Factory) ---`,
    ...manifest.environment.map((entry) => `${entry.comment ? `# ${entry.comment}\n` : ''}${entry.name}=${entry.example}`),
  ];
  const separator = current === '' || current.endsWith('\n') ? '' : '\n';
  return `${current}${separator}\n${lines.join('\n')}\n`;
}

/**
 * Orders capability seeds deterministically by their declared `order`. Rejects a
 * symbol declared twice and two seeds claiming the same slot.
 */
export function orderCapabilitySeeds(seeds) {
  const bySymbol = new Map();
  const byOrder = new Map();
  for (const seed of seeds) {
    if (bySymbol.has(seed.symbol)) throw new Error(`Duplicate capability seed: ${seed.symbol}`);
    if (byOrder.has(seed.order)) {
      throw new Error(`Ambiguous capability seed order ${seed.order}: ${byOrder.get(seed.order)} and ${seed.symbol}`);
    }
    bySymbol.set(seed.symbol, seed);
    byOrder.set(seed.order, seed.symbol);
  }
  return [...seeds].sort((a, b) => a.order - b.order);
}

/** prisma/seed/capability-seeds.ts — the seed registry consumed by the stable orchestrator. */
export function renderPrismaSeedRegistry(seeds) {
  assertKnown(seeds, ['nestjs.prisma-seed']);
  const ordered = orderCapabilitySeeds(seeds);
  const importLines = ordered.map((item) => `import { ${item.symbol} } from '${item.importPath}';`);
  const entries = ordered.map((item) => [
    '  {',
    `    capability: '${item.capability}',`,
    `    order: ${item.order},`,
    `    run: ${item.symbol},`,
    '  },',
  ].join('\n'));
  return [
    BANNER,
    "import type { PrismaClient } from '@prisma/client';",
    ...importLines,
    '',
    '/** Contexte fourni à chaque seed de capability. */',
    'export interface SeedContext {',
    '  readonly prisma: PrismaClient;',
    '}',
    '',
    '/** Seed d\'une capability : idempotent, sans identité ni donnée métier. */',
    'export interface CapabilitySeed {',
    '  readonly capability: string;',
    '  readonly order: number;',
    '  readonly run: (context: SeedContext) => Promise<void>;',
    '}',
    '',
    '/** Seeds apportés par les capabilities composées, dans l\'ordre déclaré. */',
    'export const CAPABILITY_SEEDS: readonly CapabilitySeed[] = [',
    ...entries,
    '];',
    '',
  ].join('\n');
}

/** Banner introducing the rendered Prisma composition. */
export function renderPrismaCompositionBanner(capabilities) {
  const list = capabilities.join(', ');
  return `\n// --- Prisma composition generated by Enistere Factory (capabilities: ${list}) ---\n`
    + '// Rendered from declarative capability fragments; do not edit manually.\n\n';
}
